+import { promises as fs } from "fs";
+import { dirname, join } from "path";
+import { fileURLToPath } from "url";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

+const __dirname = dirname(fileURLToPath(import.meta.url));
+const storageDir = join(__dirname, "..", ".sessions");
+
 const store = new Map<string, Entry>();

-export const put = (key: string, value: string, ttlMs: number): void => {
-  store.set(key, { value, expiresAt: Date.now() + ttlMs });
+const ensureStorageDir = async (): Promise<void> => {
+  try {
+    await fs.mkdir(storageDir, { recursive: true });
+  } catch {}
 };

-export const get = (key: string): string | null => {
-  const entry = store.get(key);
-  if (entry === undefined) return null;
-  if (entry.expiresAt < Date.now()) {
-    store.delete(key);
+const getFilePath = (key: string): string => {
+  return join(storageDir, `${key}.json`);
+};
+
+export const put = async (
+  key: string,
+  value: string,
+  ttlMs: number
+): Promise<void> => {
+  const expiresAt = Date.now() + ttlMs;
+  const entry: Entry = { value, expiresAt };
+
+  store.set(key, entry);
+
+  await ensureStorageDir();
+  await fs.writeFile(getFilePath(key), JSON.stringify(entry), "utf8");
+};
+
+export const get = async (key: string): Promise<string | null> => {
+  const memEntry = store.get(key);
+  if (memEntry !== undefined) {
+    if (memEntry.expiresAt < Date.now()) {
+      store.delete(key);
+      await fs
+        .unlink(getFilePath(key))
+        .catch(() => {});
+      return null;
+    }
+    return memEntry.value;
+  }
+
+  try {
+    const data = await fs.readFile(getFilePath(key), "utf8");
+    const entry: Entry = JSON.parse(data);
+
+    if (entry.expiresAt < Date.now()) {
+      await fs.unlink(getFilePath(key)).catch(() => {});
+      return null;
+    }
+
+    store.set(key, entry);
+    return entry.value;
+  } catch {
     return null;
   }
-  return entry.value;
 };
+
+export const restoreFromDisk = async (): Promise<void> => {
+  try {
+    const files = await fs.readdir(storageDir);
+    const now = Date.now();
+
+    for (const file of files) {
+      if (!file.endsWith(".json")) continue;
+
+      try {
+        const data = await fs.readFile(join(storageDir, file), "utf8");
+        const entry: Entry = JSON.parse(data);
+
+        if (entry.expiresAt > now) {
+          const key = file.slice(0, -5);
+          store.set(key, entry);
+        } else {
+          await fs.unlink(join(storageDir, file)).catch(() => {});
+        }
+      } catch {}
+    }
+  } catch {}
+};
+
+restoreFromDisk();
